"use client";
/* eslint-disable @typescript-eslint/no-explicit-any */
import Link from "next/link";
import {useEffect,useMemo,useState} from "react";
import {Area,AreaChart,Bar,BarChart,CartesianGrid,Cell,Legend,Line,LineChart,Pie,PieChart,ReferenceLine,ResponsiveContainer,Scatter,ScatterChart,Tooltip,XAxis,YAxis,ZAxis} from "recharts";

type Row=Record<string,string>;
type Wdi={iso3:string;pais:string;anio:number;codigo_indicador:string;valor:number};
type Data={wdi:Wdi[];ox:any[];daily:any[];loading:boolean;error:string};
const C={gdp:"NY.GDP.MKTP.KD.ZG",gdpPc:"NY.GDP.PCAP.KD.ZG",unemployment:"SL.UEM.TOTL.ZS",inflation:"FP.CPI.TOTL.ZG",gini:"SI.POV.GINI",life:"SP.DYN.LE00.IN",health:"SH.XPD.CHEX.PC.CD",population:"SP.POP.TOTL"};
const YEARS=[2015,2016,2017,2018,2019,2020,2021,2022,2023];
const COLORS=["#72ddc9","#f3b66b","#a89af5","#e58fb5","#83aef2","#d5d982"];
const POLICY:Record<string,string>={C1:"Cierre de escuelas",C2:"Cierre de lugares de trabajo",C3:"Cancelación de eventos",C4:"Límites a reuniones",C5:"Cierre del transporte público",C6:"Permanencia en el hogar",C7:"Restricciones de circulación interna",C8:"Controles de viajes internacionales",E1:"Apoyo a los ingresos",E2:"Alivio de deudas",H1:"Campañas de información",H2:"Política de pruebas",H3:"Rastreo de contactos",H6:"Uso de mascarillas",H7:"Política de vacunación",H8:"Protección de personas mayores"};
const WDI="https://databank.worldbank.org/source/world-development-indicators",OX="https://github.com/OxCGRT/covid-policy-dataset/blob/main/documentation_and_codebook.md";
const num=(v:any):number|null=>v===null||v===undefined||String(v).trim()===""||!Number.isFinite(Number(v))?null:Number(v);
const avg=(a:any[])=>{const v=a.map(num).filter((x):x is number=>x!==null);return v.length?v.reduce((s,x)=>s+x,0)/v.length:null;};
const fmt=(v:any,d=1)=>num(v)===null?"Sin dato":Number(v).toLocaleString("es-AR",{minimumFractionDigits:d,maximumFractionDigits:d});
function parseCSV(raw:string):Row[]{const lines=raw.replace(/^\uFEFF/,"").trim().split(/\r?\n/);if(lines.length<2)return[];const split=(s:string)=>{const out:string[]=[];let v="",q=false;for(let i=0;i<s.length;i++){const c=s[i];if(c==='"'&&s[i+1]==='"'&&q){v+='"';i++;}else if(c==='"')q=!q;else if(c===","&&!q){out.push(v);v="";}else v+=c;}out.push(v);return out;};const h=split(lines[0]);return lines.slice(1).map(l=>{const v=split(l);return Object.fromEntries(h.map((k,i)=>[k,v[i]??""]));});}
const axis={stroke:"#8192a9",tickLine:false,axisLine:false,tick:{fill:"#9aabc0",fontSize:10}};
const grid=<CartesianGrid stroke="#26364d" strokeDasharray="3 5"/>;
const tooltip={contentStyle:{background:"#101a2b",border:"1px solid #344861",borderRadius:10,color:"#f3f6fc"},labelStyle:{color:"#aab8ca"}};
function Sources({ox=false}:{ox?:boolean}){return <div className="source-line"><span>FUENTE</span><a href={WDI} target="_blank" rel="noreferrer">Banco Mundial · WDI</a>{ox&&<a href={OX} target="_blank" rel="noreferrer">Oxford · OxCGRT</a>}</div>;}
function Panel({title,sub,note,children,ox=false}:{title:string;sub?:string;note?:string;children:React.ReactNode;ox?:boolean}){return <article className="panel"><header><h3>{title}</h3>{sub&&<p>{sub}</p>}</header><div className="plot">{children}</div>{note&&<p className="chart-note">{note}</p>}<Sources ox={ox}/></article>;}
function Series({data,lines,x="anio",unit="",zero=false}:{data:any[];lines:{key:string;name:string;color?:string}[];x?:string;unit?:string;zero?:boolean}){return <ResponsiveContainer width="100%" height="100%"><LineChart data={data} margin={{top:10,right:12,bottom:3,left:0}}>{grid}<XAxis dataKey={x} interval={x==="mes"?2:0} {...axis}/><YAxis {...axis} tickFormatter={v=>String(fmt(v,0))+unit}/><Tooltip {...tooltip} formatter={(v,n)=>[String(fmt(v,2))+unit,n]}/>{zero&&<ReferenceLine y={0} stroke="#f3b66b" strokeDasharray="4 4"/>}<Legend wrapperStyle={{fontSize:10}}/>{lines.map((l,i)=><Line key={l.key} type="monotone" dataKey={l.key} name={l.name} stroke={l.color??COLORS[i%COLORS.length]} strokeWidth={2.3} dot={false} activeDot={{r:5}} connectNulls={false}/>)}</LineChart></ResponsiveContainer>;}
function Bars({data,keyName,unit="%",color=COLORS[0]}:{data:any[];keyName:string;unit?:string;color?:string}){return <ResponsiveContainer width="100%" height="100%"><BarChart data={data} layout="vertical" margin={{top:4,right:18,bottom:2,left:4}}><CartesianGrid stroke="#26364d" strokeDasharray="3 5" horizontal={false}/><XAxis type="number" {...axis} tickFormatter={v=>String(fmt(v,0))+unit}/><YAxis type="category" dataKey="pais" width={125} {...axis} tick={{fill:"#aab8ca",fontSize:9}}/><Tooltip {...tooltip} formatter={v=>[String(fmt(v,2))+unit,"Valor"]}/><ReferenceLine x={0} stroke="#f3b66b" strokeDasharray="4 4"/><Bar dataKey={keyName} fill={color} radius={[0,4,4,0]} maxBarSize={18}/></BarChart></ResponsiveContainer>;}
function ScatterPanel({title,data,xLabel,yLabel,xUnit="",yUnit="",zero=false}:{title:string;data:any[];xLabel:string;yLabel:string;xUnit?:string;yUnit?:string;zero?:boolean}){const [selected,setSelected]=useState<any>(null);return <Panel title={title} sub="Seleccioná un punto para ver sus valores" ox><ResponsiveContainer width="100%" height="100%"><ScatterChart margin={{top:12,right:14,bottom:22,left:4}}>{grid}<XAxis type="number" dataKey="x" name={xLabel} {...axis} tickFormatter={v=>String(fmt(v,0))+xUnit} label={{value:xLabel,position:"insideBottom",offset:-14,fill:"#9aabc0",fontSize:9}}/><YAxis type="number" dataKey="y" name={yLabel} {...axis} tickFormatter={v=>String(fmt(v,1))+yUnit} label={{value:yLabel,angle:-90,position:"insideLeft",fill:"#9aabc0",fontSize:9}}/><ZAxis range={[56,56]}/><Tooltip {...tooltip} formatter={(v,n)=>[String(fmt(v,2))+(n===xLabel?xUnit:yUnit),n]} labelFormatter={(_,p)=>p?.[0]?.payload?p[0].payload.pais+" · "+p[0].payload.anio:""}/>{zero&&<ReferenceLine y={0} stroke="#f3b66b" strokeDasharray="4 4"/>}<Scatter data={data} fill={COLORS[0]} fillOpacity={.78} onClick={(v:any)=>setSelected(v?.payload??v)}/></ScatterChart></ResponsiveContainer>{selected&&<div className="point-detail"><b>{selected.pais} · {selected.anio}</b><span>{xLabel}: {fmt(selected.x,2)}{xUnit}</span><span>{yLabel}: {fmt(selected.y,2)}{yUnit}</span><button onClick={()=>setSelected(null)}>Cerrar</button></div>}<p className="chart-note">Punto = país/año. La asociación es descriptiva; no demuestra causalidad.</p></Panel>;}
function ReachDonut({data}:{data:any[]}){const totals=[{name:"General",value:data.reduce((s,r)=>s+(r.general??0),0)},{name:"Focalizado",value:data.reduce((s,r)=>s+(r.focalizado??0),0)},{name:"Sin clasificación",value:data.reduce((s,r)=>s+(r.sinFlag??0),0)}].filter(r=>r.value>0);return <ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={totals} dataKey="value" nameKey="name" cx="50%" cy="48%" innerRadius="48%" outerRadius="76%" paddingAngle={3} label={({name,percent})=>`${name} ${((percent??0)*100).toFixed(0)}%`} labelLine={{stroke:"#8192a9"}}>{totals.map((r,i)=><Cell key={r.name} fill={COLORS[i%COLORS.length]}/>)}</Pie><Tooltip {...tooltip} formatter={(v)=>[String(fmt(v,0))+" días","Total"]}/><Legend wrapperStyle={{fontSize:10}}/></PieChart></ResponsiveContainer>;}
function ReachBars({data}:{data:any[]}){return <ResponsiveContainer width="100%" height="100%"><BarChart data={data} layout="vertical" margin={{top:4,right:18,bottom:2,left:4}}><CartesianGrid stroke="#26364d" strokeDasharray="3 5" horizontal={false}/><XAxis type="number" {...axis} tickFormatter={v=>String(fmt(v,0))}/><YAxis type="category" dataKey="pais" width={125} {...axis} tick={{fill:"#aab8ca",fontSize:9}}/><Tooltip {...tooltip}/><Legend wrapperStyle={{fontSize:10}}/><Bar dataKey="general" name="General" stackId="alcance" fill={COLORS[0]}/><Bar dataKey="focalizado" name="Focalizado" stackId="alcance" fill={COLORS[1]}/><Bar dataKey="sinFlag" name="Alcance sin dato" stackId="alcance" fill={COLORS[2]}/></BarChart></ResponsiveContainer>;}
function Kpi({label,value,detail}:{label:string;value:string;detail:string}){return <div className="kpi"><span>{label}</span><strong>{value}</strong><small>{detail}</small></div>;}
function StoryBeat({title,voice,definition,reading,bridge}:{title:string;voice:string;definition:string;reading:string;bridge:string}){return <aside className="story-beat"><div className="story-kicker">HILO CONDUCTOR · PARA NARRAR</div><h3>{title}</h3><p className="story-voice">{voice}</p><div className="story-details"><p><b>Concepto clave</b>{definition}</p><p><b>Lectura del reporte</b>{reading}</p></div><p className="story-bridge"><b>Transición</b>{bridge}</p></aside>;}

export default function Home(){
 const [page,setPage]=useState<"panorama"|"restricciones"|"impacto"|"desigualdad"|"salud"|"comparacion"|"exploracion">("panorama"),[year,setYear]=useState(2020);
 const [exploreSource,setExploreSource]=useState<"economia"|"politicas">("economia"),[exploreMetric,setExploreMetric]=useState(C.gdp),[exploreCountry,setExploreCountry]=useState("ALL"),[exploreFrom,setExploreFrom]=useState(2015),[exploreTo,setExploreTo]=useState(2023);
 const [data,setData]=useState<Data>({wdi:[],ox:[],daily:[],loading:true,error:""});
 useEffect(()=>{let live=true;Promise.all(["wdi_indicadores.csv","oxcgrt_anual.csv","oxcgrt_diario.csv"].map(f=>fetch("/data/"+f).then(r=>{if(!r.ok)throw Error("No se pudo cargar "+f);return r.text();}))).then(([w,o,d])=>{const wdi=parseCSV(w).flatMap(r=>{const v=num(r.valor);return v===null?[]:[{iso3:r.iso3,pais:r.pais,anio:+r.anio,codigo_indicador:r.codigo_indicador,valor:v}];});const ox=parseCSV(o).map(r=>Object.fromEntries(Object.entries(r).map(([k,v])=>[k,k==="iso3"?v:num(v)])));const daily=parseCSV(d).map(r=>Object.fromEntries(Object.entries(r).map(([k,v])=>[k,["iso3","fecha"].includes(k)?v:num(v)])));if(live)setData({wdi,ox,daily,loading:false,error:""});}).catch(e=>{if(live)setData({wdi:[],ox:[],daily:[],loading:false,error:e.message});});return()=>{live=false;};},[]);
 const d=useMemo(()=>{
  const s=(code:string)=>data.wdi.filter(r=>r.codigo_indicador===code);
  const region=YEARS.map(anio=>{const r:any={anio};for(const [k,c] of Object.entries(C))r[k]=avg(s(c).filter(v=>v.anio===anio).map(v=>v.valor));return r;});
  const gdp=s(C.gdp),countries=[...new Set(gdp.map(r=>r.iso3))].map(iso=>{const r=gdp.filter(v=>v.iso3===iso);return{iso3:iso,pais:r[0]?.pais??iso,contraction:r.find(v=>v.anio===2020)?.valor??null,recovery:avg(r.filter(v=>v.anio>=2021&&v.anio<=2023).map(v=>v.valor))};});
  const recoveryScatter=countries.filter(r=>r.contraction!==null&&r.recovery!==null).map(r=>({pais:r.pais,anio:2020,x:r.contraction,y:r.recovery}));
  const oxRegion=[2020,2021,2022].map(anio=>{const rows=data.ox.filter(r=>r.anio===anio);const v:any={anio};for(const k of ["StringencyIndex_Average","GovernmentResponseIndex_Average","ContainmentHealthIndex_Average","EconomicSupportIndex"])v[k]=avg(rows.map(r=>r[k]));return v;});
  const months=new Map<string,any[]>();for(const r of data.daily){const m=String(r.fecha).slice(0,7);if(!months.has(m))months.set(m,[]);months.get(m)!.push(r);}
  const monthly=[...months].sort(([a],[b])=>a.localeCompare(b)).map(([mes,rows])=>{const r:any={mes};for(const k of ["C1","C2","C3","C4","C5","C6","C7","C8","E1","E2","H1","H2","H3","H6","H7","H8"])r[k]=avg(rows.map(v=>v[k]));r.rigurosidad=avg(rows.map(v=>v.StringencyIndex_Average));return r;});
  const dur=data.ox.filter(r=>r.anio===year).map(r=>({pais:data.wdi.find(v=>v.iso3===r.iso3)?.pais??r.iso3,dias:num(r.dias_C6_obligatorio),recomendacion:num(r.dias_C6_recomendacion),estricto:num(r.dias_C6_estricto),racha:num(r.racha_max_C6_obligatorio),general:num(r.dias_C6_obligatorio_general),focalizado:num(r.dias_C6_obligatorio_focalizado),sinFlag:num(r.dias_C6_obligatorio_sin_flag)})).filter(r=>r.dias!==null).sort((a,b)=>(b.dias??0)-(a.dias??0));
  const policy=data.ox.filter(r=>r.anio===year);
  const durationGDP=policy.flatMap(o=>{const g=gdp.find(r=>r.iso3===o.iso3&&r.anio===o.anio),x=num(o.dias_C6_obligatorio);return g&&x!==null?[{pais:g.pais,anio:g.anio,x,y:g.valor}]:[];});
  const scatterGDP=data.ox.flatMap(o=>{const g=gdp.find(r=>r.iso3===o.iso3&&r.anio===o.anio),x=num(o.StringencyIndex_Average);return g&&x!==null?[{pais:g.pais,anio:g.anio,x,y:g.valor}]:[];});
  const healthPre=s(C.health).filter(r=>r.anio>=2015&&r.anio<=2019);
  const healthGDP=[...new Set(healthPre.map(r=>r.iso3))].flatMap(iso=>{const h=avg(healthPre.filter(r=>r.iso3===iso).map(r=>r.valor)),g=gdp.find(r=>r.iso3===iso&&r.anio===2020);return h!==null&&g?[{pais:g.pais,anio:2020,x:h,y:g.valor}]:[];});
  const healthLife=[...new Set(healthPre.map(r=>r.iso3))].flatMap(iso=>{const h=avg(healthPre.filter(r=>r.iso3===iso).map(r=>r.valor)),l=s(C.life).find(r=>r.iso3===iso&&r.anio===2019);return h!==null&&l?[{pais:l.pais,anio:2019,x:h,y:l.valor}]:[];});
  const pop=s(C.population).filter(r=>r.anio===2020).flatMap(p=>{const g=gdp.find(r=>r.iso3===p.iso3&&r.anio===2020);return g?[{pais:p.pais,anio:2020,x:p.valor/1e6,y:g.valor}]:[];});
  const lifeChange=s(C.life).filter(r=>r.anio===2021).flatMap(r=>{const b=s(C.life).find(v=>v.iso3===r.iso3&&v.anio===2019);return b?[{pais:r.pais,cambio:r.valor-b.valor}]:[];}).sort((a,b)=>a.cambio-b.cambio);
  const support=data.ox.flatMap(o=>{const u=s(C.unemployment).find(r=>r.iso3===o.iso3&&r.anio===o.anio),x=num(o.EconomicSupportIndex);return u&&x!==null?[{pais:u.pais,anio:u.anio,x,y:u.valor}]:[];});
  const gini2019=s(C.gini).filter(r=>r.anio===2019).map(r=>({iso3:r.iso3,pais:r.pais,valor:r.valor})).sort((a,b)=>b.valor-a.valor);
  const unemployment2020=s(C.unemployment).filter(r=>r.anio===2020).map(r=>({iso3:r.iso3,pais:r.pais,valor:r.valor})).sort((a,b)=>b.valor-a.valor);
  const giniGDP=gini2019.flatMap(r=>{const g=gdp.find(v=>v.iso3===r.iso3&&v.anio===2020);return g?[{pais:r.pais,anio:2020,x:r.valor,y:g.valor}]:[];});
  const unemploymentGDP=s(C.unemployment).filter(r=>r.anio===2019).flatMap(r=>{const u=s(C.unemployment).find(v=>v.iso3===r.iso3&&v.anio===2020),g=gdp.find(v=>v.iso3===r.iso3&&v.anio===2020);return u&&g?[{pais:r.pais,anio:2020,x:r.valor,y:g.valor,cambio:u.valor-r.valor}]:[];});
  const healthChange=[...new Set(healthPre.map(r=>r.iso3))].flatMap(iso=>{const a=s(C.health).find(r=>r.iso3===iso&&r.anio===2015),b=s(C.health).find(r=>r.iso3===iso&&r.anio===2019);return a&&b&&a.valor!==0?[{pais:b.pais,cambio:(b.valor/a.valor-1)*100}]:[];}).sort((a,b)=>b.cambio-a.cambio);
  const measures=monthly.map(r=>({mes:r.mes,C1:r.C1,C2:r.C2,C3:r.C3,C6:r.C6,C8:r.C8}));
  const comparison=countries.map(c=>{const g=gini2019.find(r=>r.iso3===c.iso3),u=unemployment2020.find(r=>r.iso3===c.iso3),l=lifeChange.find(r=>r.pais===c.pais),o=data.ox.find(r=>r.iso3===c.iso3&&r.anio===year);return{...c,gini:g?.valor??null,unemployment:u?.valor??null,lifeChange:l?.cambio??null,c6:num(o?.dias_C6_obligatorio)};});
  return{region,countries,recoveryScatter,oxRegion,monthly,measures,dur,policy,durationGDP,scatterGDP,healthGDP,healthLife,pop,lifeChange,support,gini2019,unemployment2020,giniGDP,unemploymentGDP,healthChange,comparison};
 },[data,year]);
 if(data.loading)return <main className="loading"><span/>Preparando series estadísticas…</main>;
 if(data.error)return <main className="loading">{data.error}</main>;
 const last=d.region.find(r=>r.anio===2023),shock=d.region.find(r=>r.anio===2020),rebound=d.region.find(r=>r.anio===2021);
 const contraction=d.countries.filter(r=>r.contraction!==null).sort((a,b)=>(a.contraction??0)-(b.contraction??0));
 const recovery=d.countries.filter(r=>r.recovery!==null).sort((a,b)=>(b.recovery??0)-(a.recovery??0));
 const duration=d.dur.map(r=>({pais:r.pais,dias:r.dias??0}));
 const recommended=d.dur.map(r=>({pais:r.pais,dias:r.recomendacion??0}));
 const strict=d.dur.map(r=>({pais:r.pais,dias:r.estricto??0}));
 const streak=d.dur.map(r=>({pais:r.pais,dias:r.racha??0}));
 return <main className="observatory">
  <header className="site-header"><Link className="brand" href="/">IFTS24 <span>- Análisis y exploración de datos</span></Link><nav><button className={page==="panorama"?"active":""} onClick={()=>setPage("panorama")}>01 · Panorama regional</button><button className={page==="restricciones"?"active":""} onClick={()=>setPage("restricciones")}>02 · Restricciones y economía</button><button className={page==="impacto"?"active":""} onClick={()=>setPage("impacto")}>03 · Impacto sanitario y social</button><button className={page==="desigualdad"?"active":""} onClick={()=>setPage("desigualdad")}>04 · Desigualdad y empleo</button><button className={page==="salud"?"active":""} onClick={()=>setPage("salud")}>05 · Capacidad sanitaria</button><button className={page==="comparacion"?"active":""} onClick={()=>setPage("comparacion")}>06 · Comparación de países</button><button className={page==="exploracion"?"active":""} onClick={()=>setPage("exploracion")}>07 · Exploración multidimensional</button></nav><small>2015—2023 · ALC</small></header>
  {page==="panorama"&&<section className="content">
   <div className="intro"><div><label>IFTS24 · ANÁLISIS Y EXPLORACIÓN DE DATOS · 01</label><h1>La región antes, durante y después del shock.</h1><p>Trayectorias económicas, demográficas y sociales de América Latina y el Caribe. Cada país con datos aporta el mismo peso a los promedios regionales.</p></div><aside>ALC<small>COVID—19</small></aside></div>
   <StoryBeat title="Una crisis común, trayectorias distintas" voice="“Para entender qué pasó con la región, primero miremos el punto de partida y el tamaño del shock. La pandemia interrumpió la actividad económica, pero la recuperación posterior no fue idéntica en todos los países.”" definition="El PIB real mide el valor de los bienes y servicios finales producidos, descontando los cambios de precios. Su tasa de crecimiento indica cuánto se expandió o contrajo la producción." reading="El promedio regional muestra una fuerte contracción en 2020, un rebote en 2021 y una desaceleración posterior. Es una media simple: cada país con dato pesa lo mismo, sin importar su población o tamaño económico." bridge="Si el impacto fue tan amplio, la siguiente pregunta es qué hicieron los gobiernos y cuánto duraron esas respuestas."/>
   <div className="kpis"><Kpi label="PIB · 2020" value={String(fmt(shock?.gdp))+"%"} detail="Crecimiento anual promedio"/><Kpi label="PIB · 2021" value={String(fmt(rebound?.gdp))+"%"} detail="Rebote promedio"/><Kpi label="PIB · 2023" value={String(fmt(last?.gdp))+"%"} detail="Crecimiento promedio"/><Kpi label="Desempleo · 2023" value={String(fmt(last?.unemployment))+"%"} detail="Porcentaje de fuerza laboral"/></div>
   <div className="section-title"><div><label>ACTIVIDAD ECONÓMICA</label><h2>Una crisis abrupta y una recuperación desigual</h2></div><small>WDI · 2015–2023</small></div>
   <div className="charts">
    <Panel title="Crecimiento del PIB real" sub="Promedio regional · % anual" note="Área = evolución de la tasa anual. La referencia en cero separa expansión de contracción. Media simple, sin ponderación por población o tamaño económico."><ResponsiveContainer width="100%" height="100%"><AreaChart data={d.region} margin={{top:10,right:12,bottom:3,left:0}}>{grid}<XAxis dataKey="anio" {...axis}/><YAxis {...axis} tickFormatter={v=>String(fmt(v,0))+"%"}/><Tooltip {...tooltip} formatter={v=>[String(fmt(v,2))+"%","Crecimiento del PIB"]}/><ReferenceLine y={0} stroke="#f3b66b" strokeDasharray="4 4"/><Area type="monotone" dataKey="gdp" name="PIB real" stroke={COLORS[0]} fill={COLORS[0]} fillOpacity={.2} connectNulls={false}/></AreaChart></ResponsiveContainer></Panel>
    <Panel title="Crecimiento del PIB per cápita" sub="Promedio regional · % anual"><Series data={d.region} lines={[{key:"gdpPc",name:"PIB per cápita",color:COLORS[2]}]} unit="%" zero/></Panel>
    <Panel title="Contracción del PIB en 2020" sub="Comparación por país · % anual"><Bars data={contraction} keyName="contraction"/></Panel>
    <Panel title="Crecimiento promedio 2021–2023" sub="Tasas anuales promedio por país" note="El promedio de tasas anuales no equivale al crecimiento acumulado entre 2020 y 2023."><Bars data={recovery} keyName="recovery" color={COLORS[2]}/></Panel>
    <ScatterPanel title="Contracción de 2020 y crecimiento posterior" data={d.recoveryScatter} xLabel="Crecimiento del PIB 2020" yLabel="Promedio 2021–2023" xUnit="%" yUnit="%" zero/>
    <Panel title="Inflación" sub="Variación anual del IPC"><Series data={d.region} lines={[{key:"inflation",name:"Inflación",color:COLORS[1]}]} unit="%" zero/></Panel>
    <Panel title="Desempleo" sub="Porcentaje de la fuerza laboral" note="No refleja por sí solo informalidad, subempleo ni participación laboral."><Series data={d.region} lines={[{key:"unemployment",name:"Desempleo",color:COLORS[3]}]} unit="%"/></Panel>
    <ScatterPanel title="Población y crecimiento del PIB en 2020" data={d.pop} xLabel="Población" yLabel="Crecimiento del PIB" xUnit=" M" yUnit="%" zero/>
    <Panel title="Gasto corriente en salud por habitante" sub="US$ corrientes · promedio simple" note="No está ajustado por inflación ni paridad de poder adquisitivo."><Series data={d.region} lines={[{key:"health",name:"Gasto sanitario"}]}/></Panel>
   </div><div className="method"><b>Resultado regional destacado</b><p>El crecimiento medio del PIB pasó de 0,52% en 2019 a −9,16% en 2020; luego promedió 8,06% en 2021, 7,64% en 2022 y 3,50% en 2023. Es una media simple entre países, no un agregado regional ponderado. El rebote posterior fue heterogéneo y no implica que todos los países hayan recuperado el nivel previo.</p></div>
  </section>}
  {page==="restricciones"&&<section className="content">
   <div className="intro"><div><label>RESPUESTAS GUBERNAMENTALES · 02</label><h1>Las restricciones no fueron una medida única ni constante.</h1><p>OxCGRT registra políticas oficiales. Su intensidad, alcance y duración variaron por país y a lo largo del tiempo. Para C1–C7 y H6/H8 se utiliza la versión M, que resume la política aplicable a la mayoría de la población; no necesariamente describe a todos los habitantes.</p></div><aside>POLÍTICAS<small>2020—2022</small></aside></div>
   <StoryBeat title="De la crisis a las decisiones públicas" voice="“Los gobiernos respondieron con distintas combinaciones de restricciones, recomendaciones y apoyos. No hubo una única cuarentena regional: las medidas cambiaron según el país y el momento.”" definition="El índice de rigurosidad de OxCGRT resume varias políticas de contención en una escala de 0 a 100. C6 registra requisitos de permanencia en el hogar: 0 sin medida, 1 recomendación, 2 obligación con excepciones esenciales y 3 obligación con excepciones mínimas." reading="Los días C6 ≥ 2 cuentan jornadas con obligación registrada, no días de encierro continuo ni cumplimiento individual. Además, el alcance puede ser general o focalizado. La serie M representa la política aplicable a la mayoría y esa mayoría puede cambiar." bridge="Medir la respuesta no alcanza para saber qué consecuencias tuvo. Ahora pasamos de las decisiones oficiales a los resultados humanos y sociales."/>
   <div className="coverage">OxCGRT tiene cobertura para 28 de los 33 países configurados. Los gráficos de políticas incluyen únicamente observaciones disponibles; un dato ausente no significa que no haya existido una medida.</div>
   <div className="section-title"><div><label>ÍNDICES COMPUESTOS</label><h2>Intensidad y orientación de la respuesta</h2></div><small>Escala 0–100 · promedio simple</small></div>
   <div className="charts">
    <Panel title="Índices OxCGRT" sub="Rigurosidad, respuesta gubernamental, contención/salud y apoyo económico" ox note="Los índices combinan conjuntos distintos de políticas. No son porcentajes de población confinada ni medidas de cumplimiento."><Series data={d.oxRegion} lines={[{key:"StringencyIndex_Average",name:"Rigurosidad"},{key:"GovernmentResponseIndex_Average",name:"Respuesta gubernamental",color:COLORS[1]},{key:"ContainmentHealthIndex_Average",name:"Contención y salud",color:COLORS[2]},{key:"EconomicSupportIndex",name:"Apoyo económico",color:COLORS[3]}]}/></Panel>
    <Panel title="Rigurosidad a lo largo del tiempo" sub="Promedio anual del índice"><Series data={d.oxRegion} lines={[{key:"StringencyIndex_Average",name:"Rigurosidad"}]}/></Panel>
    <ScatterPanel title="Rigurosidad y crecimiento del PIB" data={d.scatterGDP} xLabel="Índice de rigurosidad" yLabel="Crecimiento del PIB" yUnit="%" zero/>
    <ScatterPanel title="Apoyo económico y desempleo" data={d.support} xLabel="Índice de apoyo económico" yLabel="Desempleo" yUnit="%"/>
    <ScatterPanel title="Duración de la obligación C6 y crecimiento del PIB" data={d.durationGDP} xLabel="Días con C6 obligatorio" yLabel="Crecimiento del PIB" xUnit=" días" yUnit="%" zero/>
   </div>
   <div className="section-title"><div><label>MEDIDAS CONCRETAS</label><h2>Qué políticas se registraron</h2></div><small>Promedios mensuales de escalas ordinales</small></div>
   <div className="charts">
    <Panel title="Evolución mensual de restricciones" sub="Escuelas, trabajo, eventos, permanencia en el hogar y viajes" ox note="Las escalas ordinales de cada medida no son idénticas. No se deben interpretar como un índice combinado."><Series data={d.measures} x="mes" lines={[{key:"C1",name:"Escuelas"},{key:"C2",name:"Trabajo",color:COLORS[1]},{key:"C3",name:"Eventos",color:COLORS[2]},{key:"C6",name:"Permanencia en el hogar",color:COLORS[3]},{key:"C8",name:"Viajes internacionales",color:COLORS[4]}]}/></Panel>
    <Panel title="Apoyo económico a hogares" sub="Apoyo a ingresos (E1) y alivio de deuda (E2)" ox note="E1 y E2 son categorías de política ordinales, no montos monetarios ni gasto fiscal ejecutado."><Series data={d.monthly} x="mes" lines={[{key:"E1",name:"Apoyo a ingresos"},{key:"E2",name:"Alivio de deuda",color:COLORS[1]}]}/></Panel>
    <Panel title="Medidas de salud pública" sub="Pruebas, rastreo, mascarillas, vacunación y protección de mayores" ox note="Cada indicador conserva su escala ordinal y su propia definición; el promedio no mide cobertura sanitaria ni efectividad."><Series data={d.monthly} x="mes" lines={[{key:"H1",name:"Información pública"},{key:"H2",name:"Pruebas",color:COLORS[1]},{key:"H3",name:"Rastreo",color:COLORS[2]},{key:"H6",name:"Mascarillas",color:COLORS[3]},{key:"H7",name:"Vacunación",color:COLORS[4]},{key:"H8",name:"Protección de mayores",color:COLORS[5]}]}/></Panel>
    <Panel title="Nivel de permanencia en el hogar (C6)" sub="Promedio mensual de las categorías registradas" ox note="0 sin medida; 1 recomendación; 2 obligación con excepciones esenciales; 3 obligación con excepciones mínimas. La versión M puede cambiar de grupo cuando cambia la mayoría vacunada; no representa porcentaje de personas ni cumplimiento."><ResponsiveContainer width="100%" height="100%"><AreaChart data={d.monthly} margin={{top:10,right:12,bottom:4,left:0}}>{grid}<XAxis dataKey="mes" {...axis}/><YAxis domain={[0,3]} ticks={[0,1,2,3]} {...axis}/><Tooltip {...tooltip}/><Area dataKey="C6" stroke={COLORS[3]} fill={COLORS[3]} fillOpacity={.2}/></AreaChart></ResponsiveContainer></Panel>
    <Panel title="Políticas de contención por indicador" sub="Promedio nacional del año seleccionado" ox note="Cada medida conserva su propia escala. La comparación es válida dentro de cada indicador, no como ranking entre escalas."><div className="year-control">Año <select value={year} onChange={e=>setYear(+e.target.value)}><option>2020</option><option>2021</option><option>2022</option></select></div><ResponsiveContainer width="100%" height="100%"><BarChart data={Object.keys(POLICY).filter(k=>k[0]==="C").map(k=>({medida:POLICY[k],valor:avg(d.policy.map(r=>r[k]))}))} layout="vertical" margin={{left:5,right:15,top:5,bottom:3}}><CartesianGrid stroke="#26364d" strokeDasharray="3 5" horizontal={false}/><XAxis type="number" {...axis}/><YAxis type="category" dataKey="medida" width={145} {...axis} tick={{fill:"#aab8ca",fontSize:9}}/><Tooltip {...tooltip}/><Bar dataKey="valor" fill={COLORS[0]} radius={[0,4,4,0]}/></BarChart></ResponsiveContainer></Panel>
    <Panel title="Días con recomendación de permanecer en el hogar" sub="Total anual de días con C6 ≥ 1 por país" ox note="Incluye tanto recomendaciones como obligaciones. No debe confundirse con días de confinamiento obligatorio."><div className="year-control">Año <select value={year} onChange={e=>setYear(+e.target.value)}><option>2020</option><option>2021</option><option>2022</option></select></div><Bars data={recommended} keyName="dias" unit=" días" color={COLORS[1]}/></Panel>
    <Panel title="Días con obligación de permanecer en el hogar" sub="Total anual de días con C6 ≥ 2 por país" ox note="Cuenta días de la serie C6-M (política aplicable a la mayoría); el alcance territorial se desglosa aparte. No implica cumplimiento efectivo ni encierro de toda la población."><div className="year-control">Año <select value={year} onChange={e=>setYear(+e.target.value)}><option>2020</option><option>2021</option><option>2022</option></select></div><Bars data={duration} keyName="dias" unit=" días" color={COLORS[3]}/></Panel>
    <Panel title="Alcance territorial de la obligación C6" sub="Días generales, focalizados y sin clasificación de alcance" ox note="OxCGRT registra la política más estricta de la jurisdicción. La bandera distingue medidas generales (1) de medidas focalizadas (0); no equivale a la proporción de población afectada."><ReachBars data={d.dur.map(r=>({pais:r.pais,general:r.general??0,focalizado:r.focalizado??0,sinFlag:r.sinFlag??0}))}/></Panel>\n    <Panel title="Composición del alcance territorial C6" sub="Distribución regional de días registrados por tipo de alcance" ox note="Suma descriptiva de días-país; no representa la proporción de población afectada."><ReachDonut data={d.dur.map(r=>({general:r.general??0,focalizado:r.focalizado??0,sinFlag:r.sinFlag??0}))}/></Panel>
    <Panel title="Días en el nivel más estricto de C6" sub="C6 = 3 · excepciones mínimas" ox note="Los días sin dato no se consideran días sin medida."><Bars data={strict} keyName="dias" unit=" días" color={COLORS[2]}/></Panel>
    <Panel title="Racha consecutiva máxima con C6 obligatorio" sub="Máximo de días seguidos con C6 ≥ 2" ox note="Una fecha faltante o un día sin obligación interrumpe la racha."><Bars data={streak} keyName="dias" unit=" días" color={COLORS[1]}/></Panel>
   </div>
   <div className="c6-explainer"><div><label>LECTURA DEL INDICADOR · C6</label><h3>¿Qué significa cada nivel de permanencia en el hogar?</h3><p>C6 registra la política oficial de permanecer en casa, no el comportamiento real de las personas. La escala aumenta según la obligatoriedad de la medida:</p></div><div className="c6-levels"><article><b>0 · Sin medida</b><span>No se registra recomendación ni obligación.</span></article><article><b>1 · Recomendación</b><span>Se recomienda permanecer en el hogar; no es una obligación.</span></article><article><b>2 · Obligación con excepciones</b><span>Se exige permanecer en casa, con excepciones para necesidades esenciales.</span></article><article><b>3 · Obligación estricta</b><span>Se exige permanecer en casa con excepciones mínimas.</span></article></div><p className="c6-footnote">Los gráficos de duración utilizan C6-M, la política aplicable a la mayoría de la población. Ese grupo puede cambiar cuando cambia la proporción de población vacunada. OxCGRT registra la medida más estricta de la jurisdicción y distingue alcance general (flag 1) o focalizado (flag 0). Por eso, un día contabilizado no significa que toda la población haya estado confinada ni que haya cumplido la medida. Los toques de queda también pueden codificarse como nivel 2: los días no equivalen necesariamente a encierro durante las 24 horas.</p></div><div className="policy-defs"><article><label>C1—C8 · CONTENCIÓN</label><h3>Cierres y restricciones</h3><p>Escuelas, lugares de trabajo, eventos, reuniones, transporte, permanencia en el hogar, circulación interna y viajes internacionales.</p></article><article><label>E1—E2 · ECONOMÍA</label><h3>Apoyo a hogares</h3><p>Apoyo a los ingresos y alivio de deudas/contratos. No equivalen al gasto fiscal total ni garantizan recepción efectiva.</p></article><article><label>H1—H8 · SALUD</label><h3>Medidas sanitarias</h3><p>Información pública, pruebas, rastreo, mascarillas, vacunación y protección de personas mayores, entre otras.</p></article></div>
   <div className="method"><b>¿Se contempla la duración de la cuarentena?</b><p>Sí, mediante la serie diaria C6-M: días con recomendación (C6 ≥ 1), días con obligación (C6 ≥ 2), días en el nivel más estricto (C6 = 3) y racha consecutiva máxima de obligación. C6-M representa la política aplicable a la mayoría de la población, que puede cambiar entre población vacunada y no vacunada a medida que varía la tasa de vacunación. Además, OxCGRT registra la medida más estricta de la jurisdicción y una bandera que identifica si fue general o focalizada; por eso los días focalizados no deben interpretarse como confinamiento nacional. En los países con datos, el promedio simple fue de 197 días obligatorios en 2020, 228 en 2021 y 18 en 2022. La correlación lineal entre días obligatorios C6 y crecimiento del PIB en 2020 fue prácticamente nula (r ≈ 0,01); no permite concluir que la duración no haya tenido efectos, porque no controla diferencias entre países ni simultaneidad. OxCGRT también codifica los toques de queda como C6=2; por eso el conteo no representa necesariamente días completos de encierro 24/7. No existe una variable única de “cuarentena total”. C8EV registra la política de ingreso para viajeros vacunados o para todos cuando no hay diferenciación; no permite contar cuarentenas de viajeros no vacunados. C8 no se suma a C6.</p></div>
  </section>}
  {page==="impacto"&&<section className="content">
   <div className="intro"><div><label>CONSECUENCIAS SANITARIAS Y SOCIALES · 03</label><h1>La recuperación económica no resume el impacto humano.</h1><p>Esperanza de vida, gasto sanitario, desempleo y desigualdad permiten observar dimensiones complementarias. Las series no aíslan por sí solas el efecto causal de la pandemia.</p></div><aside>SALUD<small>Y SOCIEDAD</small></aside></div>
   <StoryBeat title="La economía no cuenta toda la historia" voice="“Una recuperación del PIB no significa automáticamente que la vida cotidiana haya vuelto a la situación anterior. Para ampliar la mirada, observamos indicadores sanitarios y sociales.”" definition="La esperanza de vida al nacer estima cuántos años viviría, en promedio, una persona recién nacida si se mantuvieran las tasas de mortalidad por edad del período observado." reading="La serie permite identificar cambios generales en las condiciones de salud, pero no equivale a un conteo de muertes por COVID-19 ni permite atribuir por sí sola cada variación a la pandemia." bridge="Los promedios sanitarios también pueden ocultar desigualdades. El siguiente reporte se concentra en cómo se distribuyen los ingresos y qué ocurrió en el mercado laboral."/>
   <div className="section-title"><div><label>CAPACIDAD Y RESULTADOS SANITARIOS</label><h2>Condiciones previas y evolución</h2></div><small>WDI · 2015–2023</small></div>
   <div className="charts">
    <Panel title="Esperanza de vida al nacer" sub="Años · promedio regional" note="Refleja mortalidad y condiciones generales de salud; no es una medición directa de muertes por COVID-19."><Series data={d.region} lines={[{key:"life",name:"Esperanza de vida",color:COLORS[3]}]}/></Panel>
    <Panel title="Gasto corriente en salud" sub="US$ corrientes por habitante" note="No está ajustado por inflación ni paridad de poder adquisitivo."><Series data={d.region} lines={[{key:"health",name:"Gasto sanitario"}]}/></Panel>
    <Panel title="Desigualdad de ingresos" sub="Índice de Gini · escala 0–100" note="La frecuencia de publicación es irregular. Los vacíos se conservan; no se interpolan."><Series data={d.region} lines={[{key:"gini",name:"Gini",color:COLORS[1]}]}/></Panel>
    <Panel title="Evolución del desempleo" sub="Porcentaje de la fuerza laboral"><Series data={d.region} lines={[{key:"unemployment",name:"Desempleo",color:COLORS[2]}]} unit="%"/></Panel>
    <Panel title="Cambio de esperanza de vida 2019–2021" sub="Diferencia en años por país" note="Cambio descriptivo; no se atribuye exclusivamente a COVID-19."><Bars data={d.lifeChange.map(r=>({pais:r.pais,cambio:r.cambio})).sort((a,b)=>a.cambio-b.cambio)} keyName="cambio" unit=" años" color={COLORS[3]}/></Panel>
    <Panel title="Crecimiento del PIB per cápita" sub="Variación anual promedio regional"><Series data={d.region} lines={[{key:"gdpPc",name:"PIB per cápita",color:COLORS[2]}]} unit="%" zero/></Panel>
    <ScatterPanel title="Gasto sanitario previo y contracción del PIB" data={d.healthGDP} xLabel="Gasto medio 2015–2019" yLabel="Crecimiento del PIB 2020" xUnit=" US$" yUnit="%" zero/>
    <ScatterPanel title="Gasto sanitario previo y esperanza de vida" data={d.healthLife} xLabel="Gasto medio 2015–2019" yLabel="Esperanza de vida 2019" xUnit=" US$" yUnit=" años"/>
   </div>
   <div className="method"><b>Resultados y límites de interpretación</b><p>El gasto sanitario corriente medio de 2015–2019 presenta una asociación positiva con la esperanza de vida de 2019 (r ≈ 0,52), pero esta relación refleja diferencias estructurales y no mide el efecto de una política. Su asociación con el crecimiento del PIB de 2020 es débil (r ≈ −0,21). La base actual no incorpora una serie comparable de exceso de mortalidad o mortalidad COVID-19 para todos los países seleccionados; no se presenta un ranking de muertes ni se reemplaza esa ausencia con estimaciones. Para evaluar efectos causales harían falta datos adicionales, rezagos y controles por demografía, capacidad hospitalaria y calidad de registro.</p></div>
  </section>}
  {page==="desigualdad"&&<section className="content">
   <div className="intro"><div><label>DISTRIBUCIÓN Y MERCADO LABORAL · 04</label><h1>La crisis también se expresa en el empleo y la desigualdad.</h1><p>El promedio regional oculta diferencias en las condiciones laborales y en la distribución del ingreso. Los indicadores disponibles permiten describir esas brechas, aunque no medir por sí solos la informalidad ni el impacto distributivo completo de la pandemia.</p></div><aside>TRABAJO<small>Y EQUIDAD</small></aside></div>
   <StoryBeat title="El promedio puede ocultar brechas" voice="“Dos países pueden registrar una caída económica parecida y, sin embargo, partir de realidades sociales muy diferentes. Por eso incorporamos la distribución del ingreso y el empleo.”" definition="El índice de Gini resume la desigualdad en la distribución del ingreso: 0 representa igualdad perfecta y 100 desigualdad máxima en la escala habitual del Banco Mundial. No mide riqueza ni pobreza directamente." reading="El desempleo expresa la proporción de la fuerza laboral que no tiene trabajo y está disponible y buscando empleo. Junto con Gini ayuda a describir el contexto, aunque no captura por completo informalidad, calidad del empleo ni todas las dimensiones de pobreza." bridge="Estas diferencias sociales también invitan a preguntar qué recursos sanitarios tenían los países antes de la crisis."/>
   <div className="section-title"><div><label>CONDICIONES SOCIOECONÓMICAS</label><h2>Trayectorias regionales y diferencias nacionales</h2></div><small>WDI · 2015–2023</small></div>
   <div className="charts">
    <Panel title="Desempleo a lo largo del período" sub="Porcentaje de la fuerza laboral · promedio simple"><Series data={d.region} lines={[{key:"unemployment",name:"Desempleo",color:COLORS[3]}]} unit="%"/></Panel>
    <Panel title="Desigualdad de ingresos" sub="Índice de Gini · promedio simple"><Series data={d.region} lines={[{key:"gini",name:"Gini",color:COLORS[1]}]} /></Panel>
    <Panel title="Desempleo por país en 2020" sub="Porcentaje de la fuerza laboral"><Bars data={d.unemployment2020.map(r=>({pais:r.pais,valor:r.valor}))} keyName="valor" color={COLORS[3]}/></Panel>
    <Panel title="Gini por país en 2019" sub="Último año previo al shock · escala 0–100" note="La disponibilidad del Gini varía por país; solo se muestran observaciones publicadas para 2019."><Bars data={d.gini2019.map(r=>({pais:r.pais,valor:r.valor}))} keyName="valor" color={COLORS[1]}/></Panel>
    <ScatterPanel title="Desigualdad previa y crecimiento del PIB en 2020" data={d.giniGDP} xLabel="Gini 2019" yLabel="Crecimiento del PIB 2020" yUnit="%" zero/>
    <ScatterPanel title="Desempleo previo y contracción del PIB" data={d.unemploymentGDP} xLabel="Desempleo 2019" yLabel="Crecimiento del PIB 2020" xUnit="%" yUnit="%" zero/>
   </div>
   <div className="method"><b>Lectura e interpretación</b><p>El Gini se publica con menor frecuencia que los indicadores macroeconómicos. Por eso no se completa ni interpola la serie: cada comparación utiliza únicamente países con observación. El desempleo tampoco describe por sí solo informalidad, subempleo, horas trabajadas o salida de la fuerza laboral. Las dispersiones muestran asociaciones entre condiciones previas y crecimiento de 2020; no identifican efectos causales.</p></div>
  </section>}
  {page==="salud"&&<section className="content">
   <div className="intro"><div><label>CAPACIDAD SANITARIA Y RESULTADOS · 05</label><h1>Las condiciones sanitarias previas importan para contextualizar la crisis.</h1><p>El gasto corriente en salud y la esperanza de vida permiten aproximar dimensiones de capacidad y resultados sanitarios. No sustituyen indicadores de camas, personal, vacunación efectiva ni mortalidad específica por COVID-19.</p></div><aside>SALUD<small>Y CAPACIDAD</small></aside></div>
   <StoryBeat title="La capacidad previa como contexto" voice="“Antes de comparar resultados, conviene mirar con qué recursos sanitarios contaba cada país. No es lo mismo enfrentar una emergencia con distintos niveles de inversión y condiciones de salud.”" definition="El gasto corriente en salud por habitante estima cuánto se destina al consumo de bienes y servicios sanitarios por persona. Aquí está expresado en dólares corrientes, sin ajuste por inflación ni poder adquisitivo." reading="En los datos previos a la pandemia aparece una asociación positiva entre gasto sanitario y esperanza de vida. Es una relación descriptiva: no demuestra que gastar más, por sí solo, cause una mayor esperanza de vida; también influyen ingresos, prevención, acceso y estructura demográfica." bridge="Con estas dimensiones sobre la mesa, podemos reunirlas para comparar países sin reducir realidades distintas a una sola puntuación."/>
   <div className="section-title"><div><label>RECURSOS Y RESULTADOS</label><h2>Una mirada de mediano plazo</h2></div><small>WDI · 2015–2023</small></div>
   <div className="charts">
    <Panel title="Esperanza de vida al nacer" sub="Años · promedio regional"><Series data={d.region} lines={[{key:"life",name:"Esperanza de vida",color:COLORS[3]}]}/></Panel>
    <Panel title="Gasto corriente en salud por habitante" sub="US$ corrientes · promedio simple" note="No está ajustado por inflación ni paridad de poder adquisitivo."><Series data={d.region} lines={[{key:"health",name:"Gasto sanitario"}]}/></Panel>
    <Panel title="Cambio de esperanza de vida 2019–2021" sub="Diferencia en años por país" note="Cambio descriptivo; no se atribuye exclusivamente a COVID-19."><Bars data={d.lifeChange.map(r=>({pais:r.pais,cambio:r.cambio}))} keyName="cambio" unit=" años" color={COLORS[3]}/></Panel>
    <Panel title="Variación del gasto sanitario 2015–2019" sub="Cambio porcentual por país · dólares corrientes" note="La variación nominal puede reflejar inflación y tipo de cambio, además de cambios reales en recursos."><Bars data={d.healthChange.map(r=>({pais:r.pais,cambio:r.cambio}))} keyName="cambio" unit="%" color={COLORS[2]}/></Panel>
    <ScatterPanel title="Gasto sanitario previo y esperanza de vida" data={d.healthLife} xLabel="Gasto medio 2015–2019" yLabel="Esperanza de vida 2019" xUnit=" US$" yUnit=" años"/>
    <ScatterPanel title="Gasto sanitario previo y crecimiento del PIB 2020" data={d.healthGDP} xLabel="Gasto medio 2015–2019" yLabel="Crecimiento del PIB 2020" xUnit=" US$" yUnit="%" zero/>
    <ScatterPanel title="Población y crecimiento del PIB en 2020" data={d.pop} xLabel="Población" yLabel="Crecimiento del PIB" xUnit=" millones" yUnit="%" zero/>
   </div>
   <div className="method"><b>Alcance de los indicadores</b><p>El gasto sanitario se expresa en dólares corrientes y no está ajustado por inflación ni paridad de poder adquisitivo. La esperanza de vida resume condiciones generales de mortalidad y salud; no permite atribuir variaciones a una única causa. La base no dispone de una serie comparable de exceso de mortalidad o mortalidad COVID-19 para todos los países seleccionados, por lo que no se construyen rankings con datos incompletos.</p></div>
  </section>}
  {page==="comparacion"&&<section className="content">
   <div className="intro"><div><label>ANÁLISIS MULTIDIMENSIONAL · 06</label><h1>Comparar países exige mirar más de una dimensión.</h1><p>Esta vista reúne el shock económico, la recuperación posterior y la duración registrada de las medidas de permanencia en el hogar. La comparación conserva los faltantes y permite cambiar el año de referencia de las políticas.</p></div><aside>PAÍSES<small>COMPARADOS</small></aside></div>
   <StoryBeat title="Comparar sin simplificar" voice="“Llegamos a la comparación integradora. En lugar de buscar un país ganador, ponemos lado a lado el impacto económico, la recuperación, la desigualdad, el empleo, la salud y las políticas.”" definition="Una matriz multidimensional cruza varias medidas y períodos para observar perfiles. Cada indicador conserva su unidad y su año de referencia; por eso no corresponde sumarlos en un ranking único sin una justificación metodológica." reading="El cruce entre días de obligación C6 y crecimiento del PIB en 2020 muestra una asociación lineal prácticamente nula en esta muestra. Eso no prueba que las políticas no hayan tenido efectos: la relación puede depender de la epidemia, el momento de aplicación y muchas condiciones no controladas." bridge="La última vista permite que quien observa explore esas relaciones por su cuenta, cambiando las dimensiones y el período."/>
   <div className="section-title"><div><label>ECONOMÍA COMPARADA</label><h2>Caída y recuperación por país</h2></div><small>WDI · 2020–2023</small></div>
   <div className="charts">
    <Panel title="Contracción del PIB en 2020" sub="Crecimiento anual por país"><Bars data={d.countries.filter(r=>r.contraction!==null).map(r=>({pais:r.pais,valor:r.contraction}))} keyName="valor" color={COLORS[1]}/></Panel>
    <Panel title="Crecimiento promedio 2021–2023" sub="Promedio de tasas anuales por país" note="No equivale al crecimiento acumulado del PIB en el período."><Bars data={d.countries.filter(r=>r.recovery!==null).map(r=>({pais:r.pais,valor:r.recovery}))} keyName="valor" color={COLORS[2]}/></Panel>
    <ScatterPanel title="Índice de rigurosidad y crecimiento del PIB" data={d.scatterGDP} xLabel="Rigurosidad promedio" yLabel="Crecimiento del PIB" yUnit="%" zero/>
    <ScatterPanel title="Días obligatorios C6 y crecimiento del PIB" data={d.durationGDP} xLabel="Días C6 ≥ 2" yLabel="Crecimiento del PIB" xUnit=" días" yUnit="%" zero/>
    <Panel title="Duración de la obligación de permanecer en el hogar" sub="Días C6 ≥ 2 por país y año seleccionado" ox><div className="year-control">Año <select value={year} onChange={e=>setYear(+e.target.value)}><option>2020</option><option>2021</option><option>2022</option></select></div><Bars data={d.dur.map(r=>({pais:r.pais,dias:r.dias??0}))} keyName="dias" unit=" días" color={COLORS[3]}/></Panel>
    <Panel title="Matriz comparativa de países" sub="Indicadores observados y año de política seleccionado"><div className="year-control">Año de políticas <select value={year} onChange={e=>setYear(+e.target.value)}><option>2020</option><option>2021</option><option>2022</option></select></div><div className="matrix-wrap"><table className="matrix"><thead><tr><th>País</th><th>PIB 2020</th><th>PIB prom. 21–23</th><th>Gini 2019</th><th>Desempleo 2020</th><th>Vida 19–21</th><th>Días C6 ({year})</th></tr></thead><tbody>{d.comparison.map((r:any)=><tr key={r.iso3}><td>{r.pais}</td><td>{fmt(r.contraction,1)}%</td><td>{fmt(r.recovery,1)}%</td><td>{fmt(r.gini,1)}</td><td>{fmt(r.unemployment,1)}%</td><td>{fmt(r.lifeChange,2)}</td><td>{fmt(r.c6,0)}</td></tr>)}</tbody></table></div></Panel>
   </div>
   <div className="method"><b>Cómo leer la matriz</b><p>Cada columna conserva su período y unidad: Gini corresponde a 2019; desempleo y crecimiento del PIB a 2020; recuperación al promedio de tasas anuales 2021–2023; cambio de esperanza de vida a 2019–2021; días C6 al año seleccionado. Los valores ausentes se muestran como “Sin dato”. No se construye un puntaje compuesto ni un ranking general porque las dimensiones no son equivalentes.</p></div>
  </section>}
  {page==="exploracion"&&<section className="content">
   <div className="intro"><div><label>ANÁLISIS MULTIDIMENSIONAL · 07</label><h1>Explorá los datos desde distintas dimensiones.</h1><p>Elegí una fuente, una medida, un país y un período. Los gráficos y la matriz se recalculan con los filtros activos para explorar patrones y comparar años.</p></div><aside>BI<small>EXPLORAR</small></aside></div>
   <StoryBeat title="De los reportes a la exploración" voice="“Hasta acá recorrimos una historia guiada. Ahora dejamos de mirar una selección fija y exploramos cómo cambian los resultados al elegir otra medida, otro país o período.”" definition="El análisis multidimensional organiza los datos por dimensiones —por ejemplo, país, tiempo e indicador— y medidas numéricas. Los filtros actúan como segmentadores y la matriz país por año cumple una función similar a una tabla dinámica." reading="Los patrones dependen de la fuente, la cobertura y los valores disponibles. Los faltantes no significan cero. Esta interfaz demuestra conceptos de BI y exploración; no ejecuta el motor DAX ni reemplaza Power BI." bridge="La conclusión general es que la pandemia fue un shock regional, pero sus trayectorias y consecuencias deben leerse desde varias dimensiones y con cautela: estas comparaciones describen asociaciones, no causas."/>
   <div className="explorer-controls">
    <label>FUENTE<select value={exploreSource} onChange={e=>{const v=e.target.value as "economia"|"politicas";setExploreSource(v);setExploreMetric(v==="economia"?C.gdp:"StringencyIndex_Average");setExploreFrom(v==="economia"?2015:2020);setExploreTo(v==="economia"?2023:2022);}}><option value="economia">Economía y sociedad · WDI</option><option value="politicas">Políticas públicas · OxCGRT</option></select></label>
    <label>MEDIDA<select value={exploreMetric} onChange={e=>setExploreMetric(e.target.value)}>{(exploreSource==="economia"?[{v:C.gdp,t:"Crecimiento del PIB (%)"},{v:C.gdpPc,t:"Crecimiento del PIB per cápita (%)"},{v:C.unemployment,t:"Desempleo (%)"},{v:C.inflation,t:"Inflación (%)"},{v:C.gini,t:"Índice de Gini"},{v:C.life,t:"Esperanza de vida (años)"},{v:C.health,t:"Gasto sanitario por habitante (US$)"},{v:C.population,t:"Población"}]:[{v:"StringencyIndex_Average",t:"Índice de rigurosidad"},{v:"GovernmentResponseIndex_Average",t:"Índice de respuesta gubernamental"},{v:"ContainmentHealthIndex_Average",t:"Índice de contención y salud"},{v:"EconomicSupportIndex",t:"Índice de apoyo económico"},{v:"dias_C6_obligatorio",t:"Días con obligación C6"},{v:"dias_C6_recomendacion",t:"Días con recomendación C6"}]).map(o=><option key={o.v} value={o.v}>{o.t}</option>)}</select></label>
    <label>PAÍS<select value={exploreCountry} onChange={e=>setExploreCountry(e.target.value)}><option value="ALL">Todos los países</option>{[...new Map(data.wdi.map(r=>[r.iso3,r.pais])).entries()].sort((a,b)=>String(a[1]).localeCompare(String(b[1]))).map(([iso,pais])=><option key={iso} value={iso}>{pais}</option>)}</select></label>
    <div className="range-filter"><div className="range-heading"><span>PERÍODO</span><strong>{exploreFrom} — {exploreTo}</strong></div><div className="dual-range" style={{background:`linear-gradient(to right,#34465d ${((exploreFrom-(exploreSource==="economia"?2015:2020))/(exploreSource==="economia"?8:2))*100}%,#72ddc9 ${((exploreFrom-(exploreSource==="economia"?2015:2020))/(exploreSource==="economia"?8:2))*100}%,#72ddc9 ${((exploreTo-(exploreSource==="economia"?2015:2020))/(exploreSource==="economia"?8:2))*100}%,#34465d ${((exploreTo-(exploreSource==="economia"?2015:2020))/(exploreSource==="economia"?8:2))*100}%)`}}><input aria-label="Año inicial" type="range" min={exploreSource==="economia"?2015:2020} max={exploreSource==="economia"?2023:2022} step="1" value={exploreFrom} onChange={e=>setExploreFrom(Math.min(+e.target.value,exploreTo))}/><input aria-label="Año final" type="range" min={exploreSource==="economia"?2015:2020} max={exploreSource==="economia"?2023:2022} step="1" value={exploreTo} onChange={e=>setExploreTo(Math.max(+e.target.value,exploreFrom))}/></div><div className="range-endpoints"><span>{exploreSource==="economia"?2015:2020}</span><span>{exploreSource==="economia"?2023:2022}</span></div></div>
    <button className="reset-filters" onClick={()=>{setExploreSource("economia");setExploreMetric(C.gdp);setExploreCountry("ALL");setExploreFrom(2015);setExploreTo(2023);}}>Restablecer filtros</button>
   </div>
   {(()=>{const years=(exploreSource==="economia"?YEARS:[2020,2021,2022]).filter(y=>y>=exploreFrom&&y<=exploreTo);const rows:any[]=exploreSource==="economia"?data.wdi.filter(r=>r.codigo_indicador===exploreMetric&&r.anio>=exploreFrom&&r.anio<=exploreTo).map(r=>({iso3:r.iso3,pais:r.pais,anio:r.anio,valor:r.valor})):data.ox.filter(r=>r.anio>=exploreFrom&&r.anio<=exploreTo).map(r=>({iso3:r.iso3,pais:data.wdi.find(w=>w.iso3===r.iso3)?.pais??r.iso3,anio:r.anio,valor:num(r[exploreMetric])})).filter(r=>r.valor!==null);const filtered=rows.filter(r=>exploreCountry==="ALL"||r.iso3===exploreCountry);const countries=Array.from(new Set(filtered.map(r=>r.iso3))).map(iso=>[iso,filtered.find(r=>r.iso3===iso)?.pais??iso] as [string,string]).sort((a,b)=>String(a[1]).localeCompare(String(b[1])));const series=years.map(anio=>({anio,valor:avg(filtered.filter(r=>r.anio===anio).map(r=>r.valor))}));const names:Record<string,string>={[C.gdp]:"Crecimiento del PIB",[C.gdpPc]:"Crecimiento del PIB per cápita",[C.unemployment]:"Desempleo",[C.inflation]:"Inflación",[C.gini]:"Índice de Gini",[C.life]:"Esperanza de vida",[C.health]:"Gasto sanitario por habitante",[C.population]:"Población",StringencyIndex_Average:"Índice de rigurosidad",GovernmentResponseIndex_Average:"Índice de respuesta gubernamental",ContainmentHealthIndex_Average:"Índice de contención y salud",EconomicSupportIndex:"Índice de apoyo económico",dias_C6_obligatorio:"Días con obligación C6",dias_C6_recomendacion:"Días con recomendación C6"};const metricName=names[exploreMetric]??exploreMetric;const unit=exploreSource==="economia"?([C.gdp,C.gdpPc,C.unemployment,C.inflation].includes(exploreMetric)?"%":exploreMetric===C.life?" años":exploreMetric===C.health?" US$":exploreMetric===C.population?" personas":""):exploreMetric.startsWith("dias_")?" días":"";return <><div className="explorer-summary"><div><span>MEDIDA ACTIVA</span><strong>{metricName}</strong></div><div><span>REGISTROS</span><strong>{filtered.length.toLocaleString("es-AR")}</strong></div><div><span>PAÍSES</span><strong>{countries.length}</strong></div><div><span>PERÍODO</span><strong>{exploreFrom}—{exploreTo}</strong></div></div><div className="charts"><Panel title="Evolución temporal" sub={exploreCountry==="ALL"?"Promedio simple de países con datos":"Serie del país seleccionado"} note="Promedio simple; no ponderado por población ni tamaño económico." ox={exploreSource==="politicas"}><ResponsiveContainer width="100%" height="100%"><LineChart data={series} margin={{top:10,right:12,bottom:3,left:0}}>{grid}<XAxis dataKey="anio" {...axis}/><YAxis {...axis}/><Tooltip {...tooltip} formatter={v=>[String(fmt(v,2))+unit,metricName]}/><Line dataKey="valor" name={metricName} stroke={COLORS[0]} strokeWidth={2.5} connectNulls={false} dot={{r:4}}/></LineChart></ResponsiveContainer></Panel><Panel title="Matriz país × año" sub="Filas: país · columnas: año · valores: medida" ox={exploreSource==="politicas"}><div className="matrix-wrap matrix-explorer"><table className="matrix"><thead><tr><th>País</th>{years.map(y=><th key={y}>{y}</th>)}</tr></thead><tbody>{countries.map(([iso,pais])=><tr key={iso}><td>{pais}</td>{years.map(y=>{const v=filtered.find(r=>r.iso3===iso&&r.anio===y)?.valor;return <td key={y}>{fmt(v,2)}{v===undefined?"":unit}</td>;})}</tr>)}</tbody></table></div></Panel></div><div className="method"><b>Cómo funciona la exploración</b><p>Los segmentadores seleccionan fuente, medida, país y período. La matriz funciona como una tabla dinámica y cruza país y tiempo con la medida elegida. En WDI la granularidad es país/año/indicador; en OxCGRT se utilizan agregados país/año. Los faltantes se conservan y los promedios usan observaciones disponibles. Esta interfaz reproduce conceptos de análisis multidimensional y BI; no ejecuta el motor DAX ni reemplaza Power BI.</p></div></>;})()}
  </section>}
  <footer className="site-footer"><span>IFTS24 · ANÁLISIS Y EXPLORACIÓN DE DATOS</span><span>WDI 2015–2023 · OxCGRT 2020–2022</span><a href={WDI} target="_blank" rel="noreferrer">Fuentes y definiciones</a></footer>
 </main>;
}
